Here is a C++ function that takes a reference to a `std::string` containing Markdown formatted text and returns a `std::string` containing HTML formatted text:
```cpp
#include <string>
#include <map>
#include <regex>

std::string convert_markdown_to_html(const std::string& markdown) {
    static std::map<std::string, std::string> markdown_to_html_plugins = {
        {"bold", "**"},
        {"italic", "*"},
        {"strikethrough", "~~"},
        {"code", "`"},
        {"fences", "``````"}
    };

    std::string html;

    // Iterate through the lines of the provided markdown
    for (const auto& line : std::regex_split(markdown, "\n")) {
        std::smatch match;

        // Check if the line contains any plugins
        if (std::regex_search(line, match, std::regex("\\A(!\\[(\\w*)\\])?,? \\[.*\\](.*)\\Z"))) {
            auto plugin = match[2];
            auto content = match[3];

            // Handle the plugin if it exists in the map
            if (markdown_to_html_plugins.find(plugin) != markdown_to_html_plugins.end()) {
                // Apply plugin to the content
                auto converted_content = markdown_to_html_plugins.at(plugin) + content + markdown_to_html_plugins.at(plugin);
                html += converted_content;
            }
        } else {
            html += line;
        }

        // Add a newline after each line except the last one
        if (line != "\n" && line != markdown.back()) {
            html += "\n";
        }
    }

    return html;
}
```
This function uses `std::smatch` from `<regex>` to parse the markdown for plugins and apply the corresponding HTML tags. It iterates through the lines of the provided markdown, checking each line for plugins using Regex, and adding the relevant HTML tags if found. If the line does not contain a plugin, the line is added to the HTML string as is.

