Here's a C++ program that reads a text file line by line and counts the number of occurrences of a specific word in the file:

#include <fstream>
#include <iostream>
#include <string>
using namespace std;

int main() {
  string keyword;    // The word to search for
  int word_count = 0; // Stores the count of keyword occurrences

  cout << "Enter the keyword to search for: ";
  cin >> keyword;

  // Open the text file for reading
  ifstream inputFile("text_file.txt");
  if (inputFile.is_open()) {
    string line;

    // Read the file line by line
    while (getline(inputFile, line)) {
      // Use the keyword to find the occurrences in the line
      while (line.find(keyword) != string::npos) {
        word_count++;
        line.erase(line.find(keyword), keyword.length());
      }
    }

    inputFile.close();
    cout << "The keyword '" << keyword << "' appears " << word_count
         << " times in the text file." << endl;
  } else {
    cout << "Error opening the text file!" << endl;
  }

  return 0;
}

This program uses the `ifstream` class to read the text file, and the `getline` function to read its lines. It then searches for the specified keyword in each line using the `string::find` and `string::erase` functions.

The program prompts the user to enter a keyword, and then reads through the lines of the text file and counts the keyword occurrences. Once the search is complete, it displays the total number of occurrences found.

Here's a C++ implementation of a function that finds the common elements in two given arrays without using any extra data structures:

```cpp
#include <iostream>

int* getCommonElements(int* arr1, int* arr2, int len1, int len2) {
    // if len1 is greater than or equal to len2, make len1 the smaller array
    if (len1 >= len2) {
        std::swap(arr1, arr2);
        std::swap(len1, len2);
    }

    // create an index variable to go through the len1 array
    int index = 0;

    // run through the arr1 array
    for (int i = 0; i < len1; i++) {
        // check if the current element in arr1 is also in arr2
        bool found = false;
        for (int j = 0; j < len2; j++) {
            if (arr1[i] == arr2[j]) {
                found = true;
                break;
            }
        }

        // update the result array with common elements
        if (found) {
            arr1[index] = arr1[i];
            index++;
        }
    }

    std::cout << "The common elements in arr1 and arr2 are: ";

    // return the result array
    return arr1;
}

int main() {
    int arr1[] = {1, 2, 3, 4, 5, 6, 7};
    int arr2[] = {7, 2, 5, 3, 6};
    int len1 = sizeof(arr1) / sizeof(arr1[0]);
    int len2 = sizeof(arr2) / sizeof(arr2[0]);
    int* result = getCommonElements(arr1, arr2, len1, len2);
    for (int i = 0; i < len1; i++) {
        if (i == len1 - 1) std::cout << result[i] << std::endl;
        else std::cout << result[i] << ", ";
    }
    return 0;
}
```

This function checks each element in the `arr1` array against the corresponding elements in the `arr2` array. If a match is found, the common element is added to the `result` array. The function then returns the `result` array, which contains the common elements.
